from urllib.parse import quote

def query_string(params):
    parts = []
    for k in sorted(params):
        parts.append(quote(str(k), safe='') + '=' + quote(str(params[k]), safe=''))
    return '&'.join(parts)

import json

def parse_json_response(body, status):
    if status >= 400:
        raise ValueError('http ' + str(status))
    return json.loads(body)

import json

def build_request(method, url, headers=None, json_body=None):
    hdrs = dict(headers or {})
    body = None
    if json_body is not None:
        body = json.dumps(json_body)
        hdrs.setdefault('Content-Type', 'application/json')
    return {'method': method.upper(), 'url': url, 'headers': hdrs, 'body': body}
